INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$Common wisdom has probably mistaken an effect for a cause: chocolate likely does not cause acne.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Stress hormones can cause acne, and chocolate lovers eat more chocolate when they are stressed.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The author accepts the observation that chocolate binges are followed by breakouts. What changes is the explanation. Stress causes both: it brings on the acne, and it brings on the chocolate. So the correlation is real, but chocolate is a side effect of the stress, not the cause of the acne. The author adds new evidence (the studies) to support that new reading.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Adding evidence that supports a different explanation of the same evidence.$batch06$)) v(position,label,body) WHERE e.id=$batch06$ac2f1ab5-1859-4c2d-b325-e2affab8f7fe$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
